"""Independently authored explanations in the mathematical sequence of 23.1–23.4."""
import sympy as s
import re
lessons=[];models=[]
def T(v):return s.latex(s.sympify(v))
def fmt(text):
 chunks=re.split(r'(\\\[.*?\\\]|\\\(.*?\\\))',text,flags=re.S);table=str.maketrans('⁻⁺⁰¹²³⁴⁵⁶⁷⁸⁹ⁿᵐᵏʸ','-+0123456789nmky')
 for i in range(0,len(chunks),2):
  chunks[i]=re.sub(r'\b(sin|cos|tan|sec|csc|cot)([⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿᵐ]+)([θxu])?',lambda m:r'\('+'\\'+m[1]+'^{'+m[2].translate(table)+'}'+(r'\theta' if m[3]=='θ' else (m[3] or ''))+r'\)',chunks[i])
  chunks[i]=re.sub(r'\b(sin|cos|tan|sec|csc|cot)\s*([0-9nmj]*)([θxu])',lambda m:r'\('+'\\'+m[1]+' '+m[2]+(r'\theta' if m[3]=='θ' else m[3])+r'\)',chunks[i])
  chunks[i]=re.sub(r'(?:[A-Za-zλω][⁻⁺⁰¹²³⁴⁵⁶⁷⁸⁹ⁿᵐᵏʸ]+)+',lambda m:r'\('+re.sub(r'([A-Za-zλω])([⁻⁺⁰¹²³⁴⁵⁶⁷⁸⁹ⁿᵐᵏʸ]+)',lambda z:z[1]+'^{'+z[2].translate(table)+'}',m[0])+r'\)',chunks[i])
 return ''.join(chunks)
def D(*rows):return r'\[\begin{gathered}'+r'\\'.join(rows)+r'\end{gathered}\]'
def E(code,title,question,solution,kind,**data):
 uid='FCOM-E-'+code;models.append(dict(id=uid,kind=kind,**data));return dict(title=title,question=fmt(question),solution=fmt(solution),verification=uid)
def L(key,title,summary,objective,before,ideas,method,mistakes,examples):
 lessons.append(dict(key=key,id='fp2_complex_'+key,title=title,summary=summary,objective=objective,before=fmt(before),ideas=fmt(ideas),method='<ol>'+''.join('<li>'+fmt(z)+'</li>' for z in method)+'</ol>',mistakes=[fmt(z) for z in mistakes],examples=examples))
base='/courses/maths4u-9231-fp2/topics/fp2_complex_'
def before(key):return '<p>Complete <a href="'+base+key+'">the preceding lesson</a>. Use radians and retain exact values.</p>'
L('powers','Complex powers, rotations and root arguments','Connect algebra, modulus and the angle of a complex number.',
 'Use de Moivre’s theorem for integer powers and list every root with the requested argument convention.',
 '<p>Review complex arithmetic, conjugates, the Argand diagram and the sine/cosine addition formulae. The modulus of a+bi is the non-negative square root of a²+b²; an argument is an angle modulo 2π. Review <a href="/courses/maths4u-9231-fp1/topics/fp1_induction_sums">induction</a> before the proof.</p>',
 r'''<h3>Keep modulus and argument separate</h3>'''+D(r'z=r(\cos\theta+i\sin\theta)=re^{i\theta},\qquad r>0',r'z^n=r^ne^{in\theta}\quad(n\in\mathbb Z)')+r'''<p>The zero complex number has modulus zero but no argument. A negative integer power needs a non-zero base. Multiplying non-zero complex numbers multiplies their moduli and adds their arguments modulo 2π; division divides the moduli and subtracts the arguments.</p><h3>Why the integer-power rule holds</h3><p>For n=1 the statement is the original polar representation. Suppose it holds for n=k. Multiplication by the original number, followed by the angle-addition formulae, gives the representation with modulus rᵏ⁺¹ and angle (k+1)θ. This proves the positive integer cases by induction. The zero power is 1. Taking reciprocals gives the negative cases, with reciprocal modulus and reversed angle.</p><h3>Multiplication is a rotation and a scaling</h3><p>The map w=λz, with non-zero λ, rotates about the origin through arg λ and scales distances by |λ|. A negative argument represents a clockwise rotation; adding a full turn describes the same map. Translation is a separate operation and changes the centre of a root polygon.</p><h3>An equation has all of its roots</h3>'''+D(r'z^m=Re^{i\phi}\quad(R>0)',r'z_k=R^{1/m}e^{i(\phi+2k\pi)/m}',r'k=0,1,\ldots,m-1')+r'''<p>These are m distinct roots, equally spaced on a circle. Taking only the principal mth root misses the others. Find them all first, then reduce each argument to the requested half-open interval. For a negative-power equation, first rewrite it as a positive-power equation without allowing zero.</p>''',
 ['Write the non-zero base in modulus–argument form.','Multiply or divide the argument and transform the modulus as required.','For a root equation include every 2kπ branch before division.','Reduce angles into the stated interval without duplicating an endpoint.','Check the original equation and describe any rotation about the correct centre.'],
 ['A negative exponent inverts the modulus as well as the angle.','Zero has no argument and cannot be raised to a negative power.','There are m roots of a non-zero mth-power equation, not one.','The two endpoints of a full-turn argument interval represent the same direction.','Arguments after a translation describe displacement from the centre, not from the origin.'],[
 E('P1','1 · An exact fifth power',r'<p>Evaluate \((\sqrt3+i)^5\) in Cartesian form.</p>',D(r'\sqrt3+i=2e^{i\pi/6}',r'(\sqrt3+i)^5=32e^{5i\pi/6}',r'=-16\sqrt3+16i')+'<p>The modulus is raised to the fifth power. The angle is multiplied by five, rather than exponentiated.</p>','power',base='sqrt(3)+I',power=5,value='-16*sqrt(3)+16*I'),
 E('P2','2 · A negative power',r'<p>Evaluate \((1-i)^{-3}\) exactly.</p>',D(r'1-i=\sqrt2e^{-i\pi/4}',r'(1-i)^{-3}=\frac1{2\sqrt2}e^{3i\pi/4}',r'=-\frac14+\frac14i')+'<p>Multiplying this result by (1−i)³ gives 1, providing an algebraic check.</p>','power',base='1-I',power=-3,value='(-1+I)/4'),
 E('P3','3 · Describe the complete transformation',r'<p>Let \(w=\frac{-1+i\sqrt3}{4}z\). Describe the map and find the image of z=4.</p>',D(r'\lambda=\frac12e^{2i\pi/3}',r'|\lambda|=\frac12,\qquad\arg\lambda=\frac{2\pi}{3}',r'w(4)=-1+i\sqrt3')+'<p>This is a scaling by 1/2 and an anticlockwise rotation through 2π/3 about the origin. There is no translation.</p>','transformation',factor='(-1+I*sqrt(3))/4',point='4',value='-1+I*sqrt(3)',scale='1/2',angle='2*pi/3'),
 E('P4','4 · Every cube root, with principal arguments',r'<p>Solve \(z^3=27i\), using \(-\pi\le\arg z<\pi\).</p>',D(r'27i=27e^{i\pi/2}',r'z_k=3e^{i(\pi/6+2k\pi/3)},\quad k=0,1,2',r'\arg z=\frac\pi6,\quad\frac{5\pi}{6},\quad-\frac\pi2')+'<p>The third unreduced angle is 3π/2; subtract a full turn. The roots have the same modulus 3 and three distinct directions.</p>','roots',degree=3,rhs='27*I',radius='3',angles=['1/6','5/6','-1/2'])])
L('angles','Multiple angles and exact polynomial roots','Use real and imaginary parts, then account for every algebraic root.',
 'Derive multiple-angle formulae and use them to solve polynomial equations completely.',before('powers'),
 r'''<h3>Expand one complex power</h3><p>Expand (c+is)ᵐ, set c=cos θ and s=sin θ, and equate real or imaginary parts with cos mθ or sin mθ. Eliminate the unwanted squared trigonometric term using c²+s²=1. When dividing the imaginary and real expressions, retain every non-zero-denominator restriction.</p>'''+D(r'(\cos\theta+i\sin\theta)^m',r'=\cos m\theta+i\sin m\theta',r'\tan m\theta=\frac{\operatorname{Im}(1+it)^m}{\operatorname{Re}(1+it)^m},\quad t=\tan\theta')+r'''<h3>Choose a useful substitution and interval</h3><p>For a polynomial built from a cosine identity, try x=cos θ and select 0≤θ≤π, where cosine is one-to-one. For sine, use a one-to-one interval such as −π/2≤θ≤π/2. For tangent or cotangent use a single interval of length π avoiding the poles. This prevents two different angles from being mistaken for distinct polynomial roots.</p><h3>Clearing a denominator creates candidates</h3><p>Secant and cosecant substitutions require non-zero cosine and sine. A multiple-angle quotient may also have poles. After multiplying through, check the original equation and any divided factors. A cancelled zero factor must be considered separately.</p><h3>Show completeness</h3><p>Distinct valid roots equal in number to the polynomial degree account for every root. If fewer are found, use factorisation or a separate argument to identify the remaining branches and multiplicities. A trigonometric substitution covering [−1,1] does not automatically rule out other real roots.</p><h3>Use coefficients for a final exact quantity</h3><p>Once the whole root set is established, Viète’s formulae can give sums, products and reciprocal sums without approximating the angles. Include any scaling between polynomial roots and the requested trigonometric values.</p>''',
 ['Expand the selected complex power and identify its real or imaginary part.','Eliminate the unwanted squared function and state denominator restrictions.','Choose a one-to-one angular interval for the algebraic substitution.','Find every admissible angle and check distinctness and excluded cases.','Use degree, multiplicity or factorisation to justify completeness.'],
 ['The imaginary part of i² is zero; retain the alternating signs correctly.','A quotient identity is valid only where its denominator is non-zero.','Different angles can give the same sine or cosine value.','A trigonometric substitution does not cover every real number automatically.','Scale a root sum or product when the polynomial variable has a multiplier.'],[
 E('A1','1 · A fourth-angle polynomial',r'<p>Derive cos4θ as a polynomial in c=cos θ.</p>',D(r'\operatorname{Re}(c+is)^4=c^4-6c^2s^2+s^4',r's^2=1-c^2',r'\cos4\theta=8c^4-8c^2+1')+'<p>The imaginary terms do not contribute. Expanding after replacing s² gives a whole polynomial in c.</p>','identity',expression='cos(4*x)',value='8*cos(x)**4-8*cos(x)**2+1'),
 E('A2','2 · A quotient with a restriction',r'<p>Derive tan3θ as a rational function of t=tan θ.</p>',D(r'(1+it)^3=(1-3t^2)+i(3t-t^3)',r'\tan3\theta=\frac{3t-t^3}{1-3t^2}')+'<p>Here cos θ≠0 and 1−3t²≠0. A zero real part would give a pole of the multiple-angle tangent rather than a value of this quotient.</p>','identity',expression='tan(3*x)',value='(3*tan(x)-tan(x)**3)/(1-3*tan(x)**2)'),
 E('A3','3 · Three exact real roots',r'<p>Solve \(8x^3-6x-1=0\) in cosine form.</p>',D(r'x=\cos\theta\quad\Longrightarrow\quad\cos3\theta=\frac12',r'0\le\theta\le\pi',r'\theta=\frac\pi9,\quad\frac{5\pi}{9},\quad\frac{7\pi}{9}',r'x=\cos\frac\pi9,\quad\cos\frac{5\pi}{9},\quad\cos\frac{7\pi}{9}')+'<p>The three cosine values are distinct because cosine is one-to-one on the chosen interval. They are roots of a cubic, so the list is complete.</p>','polynomial_roots',polynomial='8*x**3-6*x-1',function='cos',angles=['1/9','5/9','7/9']),
 E('A4','4 · Select all four angles',r'<p>Solve \(16x^4-16x^2+1=0\) in cosine form.</p>',D(r'\cos4\theta=\frac12,\qquad x=\cos\theta',r'\theta=\frac\pi{12},\quad\frac{5\pi}{12},\quad\frac{7\pi}{12},\quad\frac{11\pi}{12}')+'<p>Each angle lies in [0,π], and none is repeated. Four distinct roots account for the quartic. Using only the first-quadrant angles would lose the two negative roots.</p>','polynomial_roots',polynomial='16*x**4-16*x**2+1',function='cos',angles=['1/12','5/12','7/12','11/12'])])
L('harmonics','Power identities and trigonometric integrals','Reverse the multiple-angle process by pairing reciprocal powers.',
 'Express powers of sine and cosine as harmonic sums and apply them with correct scales.',before('angles')+'<p>Written integration extensions require <a href="/courses/maths4u-9231-fp2/topics/fp2_integration_techniques">integration techniques</a> and, for Q8, the reduction-formula method. Their calculus is a prerequisite application.</p>',
 r'''<h3>Pair opposite powers</h3><p>Set \(z=e^{i\theta}\). Then z+z⁻¹=2cos θ and z−z⁻¹=2i sin θ. Expand a suitable power and pair terms with exponents j and −j. Their sum gives a cosine; their difference gives a sine. This is a derivation from complex numbers rather than a quoted power-reduction formula.</p>'''+D(r'z^j+z^{-j}=2\cos j\theta',r'z^j-z^{-j}=2i\sin j\theta',r'\cos^m\theta=\frac{(z+z^{-1})^m}{2^m}',r'\sin^m\theta=\frac{(z-z^{-1})^m}{(2i)^m}')+r'''<h3>Track the power of i</h3><p>The denominator for a sine power includes iᵐ. For an even power it can be negative. For an odd power it combines with the paired sine terms. Check the final identity at a simple angle and against its symmetry, while recognising that spot checks alone are not a proof.</p><h3>Products and quotients</h3><p>Mixed powers use a product of the two Laurent expansions. For a quotient, derive numerator and denominator separately, then state where the original denominator is non-zero. Do not cancel a restriction that came from the original function.</p><h3>Integrate the complete identity</h3><p>Every non-zero-frequency sine or cosine has a frequency factor in its primitive. Under u=kx the differential contributes 1/k and both limits change. Include a constant term, symmetry factor or algebraic substitution only when justified by the stated integral.</p>''',
 ['Choose z+z⁻¹, z−z⁻¹ or their product to match the powers.','Expand and pair positive and negative exponents.','Divide by the full power of 2 and i.','For a quotient preserve its denominator restrictions.','For integration transform the variable, scale and endpoints together.'],
 ['Dividing a sine expansion by 2ᵐ alone loses iᵐ.','Pair equal-magnitude positive and negative exponents.','Odd and even powers have different harmonic patterns.','The primitive of cos(kx) contains 1/k.','A quotient identity does not remove a pole of the original function.'],[
 E('H1','1 · An odd cosine power',r'<p>Use a complex expansion to express cos⁵θ as a harmonic sum.</p>',D(r'(z+z^{-1})^5',r'=z^5+5z^3+10z+10z^{-1}+5z^{-3}+z^{-5}',r'\cos^5\theta=\frac{10\cos\theta+5\cos3\theta+\cos5\theta}{16}')+'<p>Each paired power contributes twice its cosine. Divide the full expansion by 2⁵.</p>','identity',expression='cos(x)**5',value='(10*cos(x)+5*cos(3*x)+cos(5*x))/16'),
 E('H2','2 · A mixed power and a definite integral',r'<p>Find the harmonic form of sin²θ cos²θ and integrate it from 0 to π/8.</p>',D(r'\sin^2\theta\cos^2\theta=\frac{1-\cos4\theta}{8}',r'\int_0^{\pi/8}\sin^2\theta\cos^2\theta\,d\theta',r'=\left[\frac\theta8-\frac{\sin4\theta}{32}\right]_0^{\pi/8}',r'=\frac\pi{64}-\frac1{32}')+'<p>The Laurent product (z−z⁻¹)²(z+z⁻¹)² gives the identity after division by −16. The negative denominator comes from i².</p>','integral',f='sin(x)**2*cos(x)**2',lo='0',hi='pi/8',value='pi/64-1/32'),
 E('H3','3 · A complete quotient identity',r'<p>Express tan⁴θ using only cos2θ, cos4θ and constants.</p>',D(r'8\sin^4\theta=3-4\cos2\theta+\cos4\theta',r'8\cos^4\theta=3+4\cos2\theta+\cos4\theta',r'\tan^4\theta=\frac{3-4\cos2\theta+\cos4\theta}{3+4\cos2\theta+\cos4\theta}')+'<p>The denominator equals 8cos⁴θ, so the original condition cos θ≠0 remains necessary.</p>','identity',expression='tan(x)**4',value='(3-4*cos(2*x)+cos(4*x))/(3+4*cos(2*x)+cos(4*x))'),
 E('H4','4 · A frequency changes the integral',r'<p>Evaluate \(\int_0^{\pi/8}\cos^4(2x)\,dx\) using a derived harmonic identity.</p>',D(r'\cos^4u=\frac38+\frac12\cos2u+\frac18\cos4u',r'u=2x,\qquad0\le u\le\frac\pi4',r'\int_0^{\pi/8}\cos^4(2x)\,dx',r'=\frac12\left[\frac{3u}{8}+\frac{\sin2u}{4}+\frac{\sin4u}{32}\right]_0^{\pi/4}',r'=\frac{3\pi}{64}+\frac18')+'<p>The factor 1/2 from dx=du/2 is independent of the harmonic coefficients.</p>','integral',f='cos(2*x)**4',lo='0',hi='pi/8',value='3*pi/64+1/8')])
L('unity','Roots of unity, root polygons and parameter cases','Use the whole root set, with exclusions and multiplicities.',
 'Apply root-of-unity structure to products, geometry and equations depending on parameters.',before('harmonics')+'<p>Q22 also uses a 3×3 determinant: review <a href="/courses/maths4u-9231-fp1/topics/fp1_matrices_determinants">determinants</a>. For root sums and products, use the coefficients of the complete polynomial.</p>',
 r'''<h3>The root-of-unity filter</h3><p>For \(\omega=e^{2\pi i/m}\), the mth roots of unity are 1,ω,…,ωᵐ⁻¹. Their powers make a finite geometric progression.</p>'''+D(r'\sum_{k=0}^{m-1}\omega^{jk}',r'=\begin{cases}m,&m\mid j,\\0,&m\nmid j.\end{cases}')+r'''<p>In the divisible case every term is 1; in the other case the geometric numerator is zero and the denominator is non-zero. This explains exactly which power sums survive.</p><h3>Removing a subset</h3><p>An equation obtained by multiplying by zᵈ−1 may introduce all of the dth roots of unity. Exclude them from the enlarged set, and verify the remaining roots in the original polynomial. Factorisation also makes multiplicities explicit.</p><h3>Products from factorisation</h3>'''+D(r'1+x+\cdots+x^{m-1}=\prod_{k=1}^{m-1}(x-\omega^k)',r'\prod_{k=1}^{m-1}(1-\omega^k)=m')+r'''<p>The root 1 is omitted from this product. For reciprocal sums, pair conjugate non-real roots or differentiate a suitable polynomial identity. State why every denominator is non-zero.</p><h3>Geometry about the right centre</h3><p>The roots of (z−c)ᵐ=A lie on a circle centred at c. Find the unshifted roots and then add c to each one. Their angles before translation describe the vectors z−c. To find the nearest vertex to a point d, minimise |z−d|² over every vertex; do not assume a labelled root is nearest without comparing directions.</p><h3>Parameters and repeated roots</h3><p>A substitution u=zᵐ can reduce the degree. Roots u on the unit circle give roots z on the unit circle, but coincident u-values can produce repeated z-roots. Treat the equality endpoints separately from the interval with distinct roots.</p>''',
 ['Write the complete roots or factor the reduced equation.','Separate an excluded subset before counting roots.','Use the unity filter or polynomial coefficients for sums and products.','For geometry translate the full set and compare squared distances.','Handle parameter endpoints and repeated roots separately.'],
 ['The root 1 is excluded from products over nontrivial unity roots.','Do not retain roots introduced by multiplying an equation.','Angles from a translated centre are not arguments from the origin.','All roots on a circle need not be distinct.','The nearest vertex must be justified, not inferred from a sketch alone.'],[
 E('U1','1 · Exclude the introduced roots',r'<p>Find every root of \(z^4+1=0\) by considering eighth roots of unity.</p>',D(r'(z^4-1)(z^4+1)=z^8-1',r'z=e^{ik\pi/4},\qquad k=1,3,5,7')+'<p>The even indices are exactly the fourth roots of unity and must be removed. The remaining four distinct roots satisfy the original quartic.</p>','complex_roots',polynomial='z**4+1',radius='1',angles=['1/4','3/4','5/4','7/4'],centre='0'),
 E('U2','2 · Translate the entire square',r'<p>Solve \((z+2-i)^4=81\) in Cartesian form.</p>',D(r'v=z+2-i,\qquad v^4=81',r'v=3,\quad3i,\quad-3,\quad-3i',r'z=1+i,\quad-2+4i,\quad-5+i,\quad-2-2i')+'<p>The square has centre −2+i and circumradius 3. Add the centre after finding the four unshifted roots.</p>','cartesian_roots',polynomial='(z+2-I)**4-81',roots=['1+I','-2+4*I','-5+I','-2-2*I']),
 E('U3','3 · A product and a reciprocal sum',r'<p>Let \(\omega=e^{2\pi i/5}\). Find \(\prod_{k=1}^4(1-\omega^k)\) and \(\sum_{k=1}^4(1-\omega^k)^{-1}\).</p>',D(r'\prod_{k=1}^4(x-\omega^k)=1+x+x^2+x^3+x^4',r'\prod_{k=1}^4(1-\omega^k)=5',r'\frac1{1-\omega^k}+\frac1{1-\omega^{-k}}=1',r'\sum_{k=1}^4\frac1{1-\omega^k}=2')+'<p>There are two conjugate pairs, and none contains 1. Each pair contributes 1 to the reciprocal sum.</p>','unity_product',degree=5,product='5',reciprocal='2'),
 E('U4','4 · A full parameter interval and its endpoints',r'<p>For real a, when do all roots of \(z^6-2az^3+1=0\) have modulus 1? When are they distinct?</p>',D(r'u=z^3,\qquad u^2-2au+1=0',r'u=a\pm\sqrt{a^2-1}',r'\text{All roots have modulus 1: }-1\le a\le1',r'\text{Six distinct roots: }-1<a<1')+'<p>Inside the interval the two u-values are distinct conjugates of modulus 1. Each has three distinct cube roots, and the two families do not overlap. At a=1 the polynomial is (z³−1)²; at a=−1 it is (z³+1)². Each endpoint has three distinct roots, each of multiplicity two. Outside the interval the real reciprocal u-values cannot both have modulus 1.</p>','parameter',degree=3)])
L('sums','Finite, binomial and convergent complex sums','Sum the complex expression first, then take its real or imaginary part.',
 'Derive complete trigonometric sums, including exceptional ratios and convergence conditions.',before('unity')+'<p>Q52 uses <a href="/courses/maths4u-9231-fp2/topics/fp2_integration_limits">rectangle bounds</a>; Q57–58 differentiate a finite sum. These prerequisite links do not add new requirements to the complex-number identities.</p>',
 r'''<h3>Identify first term, ratio and number of terms</h3>'''+D(r'\sum_{r=0}^{n-1}aq^r=a\frac{1-q^n}{1-q}\quad(q\ne1)',r'\sum_{r=0}^{n-1}a=na\quad(q=1)')+r'''<p>For a trigonometric progression, encode the phase and frequency in the first term and ratio. Sum before taking the real or imaginary part. If the ratio is 1, evaluate the finite sum directly; the quotient formula has an excluded denominator.</p><h3>Rewrite a complex difference carefully</h3>'''+D(r'1-e^{iu}=-2ie^{iu/2}\sin\frac u2')+r'''<p>This identity separates a phase from a sine factor. The sine factor can be negative, so an exponential times a real sine quotient is not automatically a polar form with positive modulus. State the necessary non-zero-sine restrictions and then handle exceptional angles directly.</p><h3>Binomial coefficients and weights</h3>'''+D(r'\sum_{r=0}^n\binom nr z^r=(1+z)^n',r'\sum_{r=0}^nr\binom nr z^r=nz(1+z)^{n-1}')+r'''<p>The weighted identity follows by differentiating the finite polynomial and multiplying by z. Alternatively use r times n-choose-r = n times (n−1)-choose-(r−1), then change the index. Derivatives of finite trigonometric sums can be taken term by term; track the sign when differentiating a cosine.</p><h3>Infinite sums need a modulus test</h3>'''+D(r'\sum_{r=1}^{\infty}(\rho e^{i\theta})^r=\frac{\rho e^{i\theta}}{1-\rho e^{i\theta}},\quad|\rho|<1')+r'''<p>The tail tends to zero because the ratio has modulus less than 1. Multiply numerator and denominator by the conjugate to extract both components. A finite cancellation at a root of unity does not justify an infinite geometric sum of modulus 1.</p>''',
 ['Encode the actual first term, ratio, phase and term count.','Use a finite geometric or binomial identity with its restrictions.','Simplify the full complex expression before taking real and imaginary parts.','Evaluate excluded ratios or angles directly.','For an infinite sum prove the ratio modulus is less than 1.'],
 ['A sum from r=0 to n−1 has n terms; a sum to n has n+1.','A phase shift belongs in the complex first term.','Evaluate the ratio-one case directly.','An infinite geometric series needs |q|<1.','Differentiating cos(rθ) produces a negative sign and a factor r.'],[
 E('S1','1 · A finite non-unit ratio',r'<p>Find \(\sum_{k=0}^{5}(1+i)^k\) in Cartesian form.</p>',D(r'\sum_{k=0}^{5}(1+i)^k=\frac{1-(1+i)^6}{1-(1+i)}',r'(1+i)^6=-8i',r'\frac{1+8i}{-i}=-8+i')+'<p>The modulus √2 is greater than 1, but that does not prevent summing six terms. It would prevent the corresponding infinite geometric sum.</p>','finite',ratio='1+I',terms=6,value='-8+I'),
 E('S2','2 · Extract both components of a trigonometric sum',r'<p>Find \(\sum_{r=1}^{4}\cos(r\pi/3)\) and \(\sum_{r=1}^{4}\sin(r\pi/3)\).</p>',D(r'q=e^{i\pi/3},\qquad\sum_{r=1}^4q^r=\frac{q(1-q^4)}{1-q}',r'=-\frac32+\frac{\sqrt3}{2}i')+'<p>The two requested sums are respectively the real and imaginary parts. Direct exact-angle values provide a separate check.</p>','finite',ratio='exp(I*pi/3)',terms=4,start=1,value='-3/2+I*sqrt(3)/2'),
 E('S3','3 · A weighted binomial sum',r'<p>Find the real and imaginary parts of \(\sum_{r=0}^{4}r\binom4r i^r\).</p>',D(r'\sum_{r=0}^4r\binom4r z^r=4z(1+z)^3',r'4i(1+i)^3=-8-8i')+'<p>The cosine-weighted sum at angle π/2 is −8, and the sine-weighted sum is −8. The zero-index term contributes zero.</p>','binomial',degree=4,ratio='I',weighted=True,value='-8-8*I'),
 E('S4','4 · Two convergent infinite sums',r'<p>Find \(C=\sum_{r=1}^{\infty}3^{-r}\cos(r\pi/3)\) and \(S=\sum_{r=1}^{\infty}3^{-r}\sin(r\pi/3)\).</p>',D(r'q=\frac13e^{i\pi/3},\qquad|q|=\frac13<1',r'C+iS=\frac q{1-q}=\frac1{14}+\frac{3\sqrt3}{14}i',r'C=\frac1{14},\qquad S=\frac{3\sqrt3}{14}')+'<p>The conjugate denominator gives a real positive denominator. The modulus condition justifies taking the infinite geometric sum.</p>','infinite',ratio='exp(I*pi/3)/3',value='1/14+3*I*sqrt(3)/14')])
